<?php
use App\Models\{OAuth,McpToken};
use App\Mcp\OAuthError;
use App\Core\DB;
function rejectsOAuth(callable $fn,string $name): void { try { $fn(); } catch(OAuthError) { check(true,$name);return; } throw new RuntimeException('ÉCHEC : '.$name); }
$oauthUser=DB::one('SELECT * FROM users WHERE id=?',[$uid]);
$public=OAuth::createClient('Client public de test','https://client.example/callback','none');
$confidential=OAuth::createClient('Client confidentiel','https://client.example/callback','client_secret_post');
$basic=OAuth::createClient('Client Basic','https://client.example/callback','client_secret_basic');
check($public['secret']===null && $confidential['secret']!==null,'clients OAuth publics et confidentiels préenregistrés');
check(!str_contains(json_encode(DB::one('SELECT * FROM oauth_clients WHERE id=?',[$confidential['id']])),$confidential['secret']),'secret client OAuth conservé sous empreinte');
rejects(fn()=>OAuth::createClient('Unsafe','https://client.example/callback#fragment','none'),'rappel OAuth avec fragment refusé');
$client=OAuth::authenticateClient(['client_id'=>$public['id']],'');
check(OAuth::authenticateClient(['client_id'=>$confidential['id'],'client_secret'=>$confidential['secret']],'')['id']===$confidential['id'],'authentification client_secret_post');
check(OAuth::authenticateClient(['client_id'=>$basic['id']],'Basic '.base64_encode($basic['id'].':'.$basic['secret']))['id']===$basic['id'],'authentification client_secret_basic');
rejectsOAuth(fn()=>OAuth::authenticateClient(['client_id'=>$confidential['id'] ],''),'secret obligatoire pour un client confidentiel');
rejectsOAuth(fn()=>OAuth::authenticateClient(['client_id'=>$public['id'],'client_secret'=>'wrong'],''),'méthode d’authentification client non déclarée refusée');
$verifier=str_repeat('v',64);$challenge=rtrim(strtr(base64_encode(hash('sha256',$verifier,true)),'+/','-_'),'=');
$params=['client_id'=>$client['id'],'response_type'=>'code','redirect_uri'=>$client['redirect_uri'],'scope'=>'read write offline_access','resource'=>url('/mcp'),'code_challenge_method'=>'S256','code_challenge'=>$challenge,'state'=>'opaque-state'];
$request=OAuth::authorization($params);
foreach(['redirect_uri'=>'https://other.example/callback','resource'=>'https://other.example/mcp','code_challenge_method'=>'plain','response_type'=>'token','scope'=>'openid'] as $field=>$value) rejectsOAuth(fn()=>OAuth::authorization(array_replace($params,[$field=>$value])),'paramètre OAuth incompatible refusé : '.$field);
rejectsOAuth(fn()=>OAuth::code($request,$oauthUser,['admin']),'consentement ne peut pas ajouter une portée non demandée');
$raw=OAuth::code($request,$oauthUser,['read','write','offline_access']);
$exchange=['code'=>$raw,'redirect_uri'=>$client['redirect_uri'],'code_verifier'=>$verifier,'resource'=>url('/mcp')];
rejectsOAuth(fn()=>OAuth::exchange($client,array_replace($exchange,['code_verifier'=>str_repeat('x',64)])),'PKCE incorrect refusé');
rejectsOAuth(fn()=>OAuth::exchange($client,array_replace($exchange,['redirect_uri'=>'https://client.example/other'])),'échange lié à l’URL de rappel exacte');
$tokens=OAuth::exchange($client,$exchange);
check(McpToken::authenticate($tokens['access_token'])['scopes']===['read','write'] && $tokens['expires_in']<=3600 && isset($tokens['refresh_token']),'code échangé en accès MCP court et renouvellement OAuth');
rejectsOAuth(fn()=>OAuth::exchange($client,$exchange),'code OAuth à usage unique');
$next=OAuth::refresh($client,['refresh_token'=>$tokens['refresh_token'],'resource'=>url('/mcp')]);
check($next['refresh_token']!==$tokens['refresh_token'] && McpToken::authenticate($next['access_token'])!==null,'renouvellement avec rotation du refresh token');
rejectsOAuth(fn()=>OAuth::refresh($client,['refresh_token'=>$next['refresh_token'],'resource'=>url('/mcp'),'scope'=>'admin offline_access']),'renouvellement sans escalade de droits');
rejectsOAuth(fn()=>OAuth::refresh($client,['refresh_token'=>$tokens['refresh_token'],'resource'=>url('/mcp')]),'ancien refresh token réutilisé refusé');
check(McpToken::authenticate($next['access_token'])===null,'réutilisation d’un ancien refresh token révoque toute l’autorisation');
$raw=OAuth::code($request,$oauthUser,['read','offline_access']);
$tokens=OAuth::exchange($client,array_replace($exchange,['code'=>$raw]));
$narrow=OAuth::refresh($client,['refresh_token'=>$tokens['refresh_token'],'resource'=>url('/mcp'),'scope'=>'read']);
check(!isset($narrow['refresh_token']) && McpToken::authenticate($narrow['access_token'])['scopes']===['read'],'retrait de offline_access coupe le renouvellement futur');
rejectsOAuth(fn()=>OAuth::exchange(OAuth::client($confidential['id']),array_replace($exchange,['code'=>OAuth::code($request,$oauthUser,['read'])])),'code lié à son client même si un autre client est authentifié');
rejectsOAuth(fn()=>OAuth::exchange($client,array_replace($exchange,['resource'=>'https://other.example/mcp'])),'ressource étrangère refusée à l’échange de jeton');
$raw=OAuth::code($request,$oauthUser,['read','offline_access']);
$tokens=OAuth::exchange($client,array_replace($exchange,['code'=>$raw]));
OAuth::revoke($client,$tokens['refresh_token']);
check(McpToken::authenticate($tokens['access_token'])===null,'révocation OAuth supprime aussi les accès MCP liés');
$raw=OAuth::code($request,$oauthUser,['read']);
$tokens=OAuth::exchange($client,array_replace($exchange,['code'=>$raw]));
check(!isset($tokens['refresh_token']),'sans offline_access aucun renouvellement accordé');
$record=McpToken::authenticate($tokens['access_token']);McpToken::remove($record['token_id'],$uid);
check(McpToken::authenticate($tokens['access_token'])===null,'suppression d’une clé OAuth révoque son autorisation');
$raw=OAuth::code($request,$oauthUser,['read','offline_access']);
$tokens=OAuth::exchange($client,array_replace($exchange,['code'=>$raw]));
DB::run('UPDATE users SET auth_version=auth_version+1 WHERE id=?',[$uid]);
check(McpToken::authenticate($tokens['access_token'])===null,'changement de version du compte invalide OAuth');
rejectsOAuth(fn()=>OAuth::refresh($client,['refresh_token'=>$tokens['refresh_token'],'resource'=>url('/mcp')]),'changement d’accès bloque le renouvellement');
DB::run('UPDATE users SET auth_version=auth_version-1 WHERE id=?',[$uid]);
$raw=OAuth::code($request,$oauthUser,['read']);DB::run('UPDATE oauth_codes SET expires_at=UTC_TIMESTAMP()-INTERVAL 1 SECOND WHERE code_hash=?',[hash('sha256',$raw)]);
rejectsOAuth(fn()=>OAuth::exchange($client,array_replace($exchange,['code'=>$raw])),'code OAuth expiré refusé');
